/** CWP -> IWP 계층 트리로 가공한 목록 */
export function getAwpCwpGroups(): AwpCwpGroup[] {
  const cwpMap = new Map<string, Map<string, { iwpNo: string; iwpName: string; lines: AwpLineItem[] }>>()

  for (const item of AWP_RAW_LIST) {
    if (!cwpMap.has(item.cwpNo)) {
      cwpMap.set(item.cwpNo, new Map())
    }
    const iwpMap = cwpMap.get(item.cwpNo)!
    if (!iwpMap.has(item.iwpNo)) {
      iwpMap.set(item.iwpNo, {
        iwpNo: item.iwpNo,
        iwpName: item.iwpName,
        lines: [],
      })
    }
    iwpMap.get(item.iwpNo)!.lines.push(item)
  }

  const groups: AwpCwpGroup[] = []
  for (const [cwpNo, iwpMap] of cwpMap.entries()) {
    const iwps: AwpIwpGroup[] = []
    let totalLines = 0
    for (const [iwpNo, data] of iwpMap.entries()) {
      iwps.push({
        cwpNo,
        iwpNo,
        iwpName: data.iwpName,
        lines: data.lines,
      })
      totalLines += data.lines.length
    }
    groups.push({
      cwpNo,
      iwps,
      totalLines,
    })
  }

  return groups.sort((a, b) => b.totalLines - a.totalLines)
}

/** 3D 선택 부재명이나 경로가 주어졌을 때 매칭되는 AWP 라인 항목 찾기 */
export function findAwpItemByNode(nameOrPath: string | null | undefined): AwpLineItem | undefined {
  if (!nameOrPath) return undefined
  const clean = nameOrPath.trim().toUpperCase()
  const cleanNoSlash = clean.replace(/^\/+/, '')
  if (cleanNoSlash.length < 5) return undefined
  return AWP_RAW_LIST.find((it) => {
    const itLine = (it.lineName || '').toUpperCase()
    const itLineNoSlash = itLine.replace(/^\/+/, '')
    const itIso = (it.isoNo || '').toUpperCase()

    if (itLine && clean.includes(itLine)) return true
    if (itLineNoSlash && cleanNoSlash.includes(itLineNoSlash)) return true
    if (itIso && clean.includes(itIso)) return true
    return false
  })
}
